if (!global.windSum) global.windSum = 0;
if (!global.windCount) global.windCount = 0;
if (!global.windAverage) global.windAverage = 0;

global.wind_tick = function() {
    try {
        var currentWind = Hub.getAccessory(537).getService(40).getCharacteristic(42).value;

        if (currentWind === null || isNaN(currentWind)) {
            log.warn("⚠️ Скорость ветра недоступна, пропускаем.");
            return;
        }

        global.windSum += currentWind;
        global.windCount += 1;

    } catch (e) {
        log.error("⛔ Ошибка wind_tick: " + e.message);
    }
};

global.wind_calc = function() {
    try {
        if (global.windCount === 0) {
            log.warn("⚠️ Нет данных по скорости ветра за период.");
            return;
        }

        global.windAverage = Math.round(global.windSum / global.windCount);

        log.info("✅ Средняя скорость ветра за период: " + global.windAverage + " (из " + global.windCount + " значений)");

        Hub.getAccessory(537).getService(75).getCharacteristic(77).setValue(global.windAverage);

        global.windSum = 0;
        global.windCount = 0;

    } catch (e) {
        log.error("⛔ Ошибка wind_calc: " + e.message);
    }
};
